# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">3. TEMA: FARKLI DÜNYALAR — «OVA ÇOCUK» METNİ VE KÜLTÜRLER</text>\n  <rect x="20" y="48" width="320" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">«Ova Çocuk» Metni ve Tema Değerleri</text>\n  <text x="38" y="98" font-size="11.5" fill="#1e3a8a">• Farklı coğrafyalarda ve ülkelerde yaşayan</text>\n  <text x="38" y="116" font-size="11.5" fill="#1e3a8a">insanların kültürlerini merak ve saygıyla tanıma.</text>\n  <text x="38" y="140" font-size="11.5" fill="#1e3a8a">• Empati ve Açık Fikirlilik: Ön yargısız yaklaşım,</text>\n  <text x="38" y="158" font-size="11.5" fill="#1e3a8a">farklılıkları zenginlik olarak görme bilinci.</text>\n  <text x="38" y="182" font-size="11.5" fill="#1e3a8a">• Metnin Bölümleri: Serim (Giriş), Düğüm (Gelişme)</text>\n  <text x="38" y="200" font-size="11.5" fill="#1e3a8a">ve Çözüm (Sonuç) basamaklarının çözümlenmesi.</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Bağlamdan Söz Varlığı Tahmini (T.O.6.5)</text>\n\n  <rect x="360" y="48" width="320" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Beden Dili ve Çoklu Ortam Ögeleri</text>\n  <text x="378" y="98" font-size="11.5" fill="#14532d">• Jest (el, kol, baş hareketleri) ve Mimik (yüz</text>\n  <text x="378" y="116" font-size="11.5" fill="#14532d">ifadeleri) sözlü iletişimi ve anlamı güçlendirir.</text>\n  <text x="378" y="140" font-size="11.5" fill="#14532d">• Kültürler arasında selamlaşma ve beden dili</text>\n  <text x="378" y="158" font-size="11.5" fill="#14532d">hareketleri hem ortaklık hem farklılık gösterebilir.</text>\n  <text x="378" y="182" font-size="11.5" fill="#14532d">• Çoklu Ortam (harita, fotoğraf, tablo, ses):</text>\n  <text x="378" y="200" font-size="11.5" fill="#14532d">Anlamı destekleme ve eş anlam oluşturma işlevi.</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Düşünceyi Geliştirme: Karşılaştırma ve Örneklendirme</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZCÜK HÂLİNDEKİ ZAMİRLER (ADILLAR) TABLOSU</text>\n  <rect x="20" y="48" width="320" height="92" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">1. Kişi (Şahıs) Zamirleri</text>\n  <text x="35" y="94" font-size="11.5" fill="#713f12">• İnsan isimlerinin yerini tutar: ben, sen, o,</text>\n  <text x="35" y="112" font-size="11.5" fill="#713f12">biz, siz, onlar + dönüşlülük zamiri «kendi».</text>\n  <text x="180" y="130" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Örnek: «Ben ve o, ödevi kendimiz yaptık.»</text>\n\n  <rect x="360" y="48" width="320" height="92" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="520" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">2. İşaret (Gösterme) Zamirleri</text>\n  <text x="375" y="94" font-size="11.5" fill="#831843">• Varlıkların yerini işaret yoluyla tutar: bu, şu,</text>\n  <text x="375" y="112" font-size="11.5" fill="#831843">o, bunlar, şunlar, onlar, burası, şurası, orası.</text>\n  <text x="520" y="130" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Örnek: «Bunu kütüphaneden aldım, şurası çok sakin.»</text>\n\n  <rect x="20" y="150" width="320" height="92" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="180" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">3. Belgisiz Zamirler</text>\n  <text x="35" y="196" font-size="11.5" fill="#581c87">• Varlıkların yerini kesin olmayacak biçimde tutar:</text>\n  <text x="35" y="214" font-size="11.5" fill="#581c87">herkes, kimse, bazıları, hepsi, çoğu, biri, birkaçı.</text>\n  <text x="180" y="232" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Örnek: «Salondakilerin bazıları şiir okudu.»</text>\n\n  <rect x="360" y="150" width="320" height="92" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="172" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">4. Soru Zamirleri</text>\n  <text x="375" y="196" font-size="11.5" fill="#155e75">• İsimlerin yerini soru yoluyla tutar: kim, ne,</text>\n  <text x="375" y="214" font-size="11.5" fill="#155e75">hangisi, kaçı, nereye, nerede, nereden, neyi.</text>\n  <text x="520" y="232" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">Örnek: «Tatilde nereye gittiniz, size kim katıldı?»</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KRİTİK AYRIM: «O» SÖZCÜĞÜ VE ZAMİR – SIFAT FARKI</text>\n  <rect x="25" y="48" width="650" height="92" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">1. «O / Onlar» Sözcüğü: Kişi Zamiri mi, İşaret Zamiri mi, İşaret Sıfatı mı?</text>\n  <text x="45" y="96" font-size="11.5" fill="#9a3412">• İnsan isminin yerini tutarsa KİŞİ ZAMİRİ: «O, yarın bize gelecek.» (Ahmet yarın bize gelecek.)</text>\n  <text x="45" y="114" font-size="11.5" fill="#9a3412">• İnsan dışı varlığın yerini tutarsa İŞARET ZAMİRİ: «Onu rafa yerleştirdim.» (Dergiyi rafa yerleştirdim.)</text>\n  <text x="45" y="132" font-size="11.5" fill="#9a3412">• Bir ismin önüne gelip o ismi işaret ederse İŞARET SIFATI: «O dergiyi rafa yerleştirdim.»</text>\n\n  <rect x="25" y="152" width="650" height="90" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Sıfat ile Zamir Ayrımı (Bu, Şu, Bazı, Birkaç, Hangi)</text>\n  <text x="45" y="200" font-size="11.5" fill="#14532d">• İsimden önce gelip ismi belirtirse SIFAT: «Bazı öğrenciler», «Birkaç soru», «Hangi ülke?»</text>\n  <text x="45" y="222" font-size="11.5" fill="#14532d">• İsmin yerini tutarsa (çekim eki alırsa) ZAMİR: «Öğrencilerin bazıları», «Soruların birkaçı», «Hangisi?»</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
